@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<p>Welcome to the logistics shipment tracking portal.</p>

<AuthorizeView>
    <Authorized>
        <p>You are signed in as <strong>@context.User.Identity?.Name</strong>.</p>
        <AuthorizeView Roles="Dispatcher">
            <Authorized>
                <p><a href="/shipments" class="btn btn-primary">Go to Dispatch Dashboard</a></p>
            </Authorized>
        </AuthorizeView>
        <p><a href="/my-shipments" class="btn btn-outline-primary">View My Shipments</a></p>
    </Authorized>
    <NotAuthorized>
        <p>Track a shipment by entering a tracking number below, or <a href="Account/Login">sign in</a> for full access.</p>
    </NotAuthorized>
</AuthorizeView>

<hr />

<h3>Track a Shipment</h3>
<div class="input-group mb-3" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-001-2026)"
           @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
    <button class="btn btn-success" @onclick="Track">Track</button>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found for "<strong>@searchedNumber</strong>".</div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> <span class="badge bg-info">@shipment.Status</span></p>
            <p><strong>Origin:</strong> @shipment.Origin</p>
            <p><strong>Destination:</strong> @shipment.Destination</p>
            <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</p>
        </div>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool searched;

    private async Task Track()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Track();
    }
}

