@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]

<PageTitle>Dispatch Dashboard</PageTitle>

<h2>Dispatch Dashboard</h2>

<div class="mb-3" style="max-width: 400px;">
    <input type="text" class="form-control" placeholder="Filter by destination or status..."
           @bind="filter" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else if (!FilteredShipments.Any())
{
    <p class="text-muted">No shipments match your filter.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Status</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
