@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using System.Security.Claims
@attribute [Authorize]

<PageTitle>My Shipments</PageTitle>

<h2>My Shipments</h2>

@if (shipments is null)
{
    <p>Loading your shipments...</p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">You have no shipments on record.</div>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between">
                        <strong>@s.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Estimated Delivery:</strong>
                            @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                        </p>
                        @if (s.Status == "Delivered")
                        {
                            <p class="text-success fw-bold mb-0">✓ Delivered</p>
                        }
                        else if (s.EstimatedDelivery.HasValue)
                        {
                            var daysLeft = (s.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                            <p class="mb-0 @(daysLeft <= 1 ? "text-warning" : "text-muted")">
                                @(daysLeft > 0 ? $"Arriving in ~{daysLeft} day(s)" : "Arriving today")
                            </p>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [CascadingParameter] private Task<AuthenticationState> AuthStateTask { get; set; } = default!;

    private List<ShipmentDto>? shipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateTask;
        var email = authState.User.FindFirst(ClaimTypes.Email)?.Value
                 ?? authState.User.FindFirst(ClaimTypes.Name)?.Value
                 ?? string.Empty;

        if (!string.IsNullOrEmpty(email))
        {
            shipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        }
        else
        {
            shipments = [];
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

